line 9516 task_idx 6 code def verify_task_completion(initial_db_path: str, final_db_path: str, final_answer: str | None = None) -> dict:
    import sqlite3
    import json
    from datetime import datetime

    def safe_query(db_path: str, query: str, params: tuple = ()) -> list:
        try:
            conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
            cursor = conn.cursor()
            cursor.execute(query, params)
            results = cursor.fetchall()
            conn.close()
            return results
        except Exception:
            return []

    # Check if segment 'Lapsed Major Donors' exists in final database
    segment_query = "SELECT id, name, description, segment_type, definition_json FROM segments WHERE name = ?"
    segments = safe_query(final_db_path, segment_query, ('Lapsed Major Donors',))

    if not segments or len(segments) == 0:
        return {"result": "others"}

    segment_id = segments[0][0]
    segment_name = segments[0][1]
    segment_definition_json = segments[0][4]

    # Verify segment name is exactly 'Lapsed Major Donors'
    if segment_name != 'Lapsed Major Donors':
        return {"result": "others"}

    # Parse and verify segment definition
    try:
        definition = json.loads(segment_definition_json) if segment_definition_json else {}
    except:
        return {"result": "others"}

    # Check if definition contains correct criteria
    # Should reference 2023, minimum total of 1000, and no gifts since 2024-01-01
    has_year_2023 = str(definition.get('year')) == '2023' or '2023' in str(definition)
    has_min_1000 = definition.get('min_total') == 1000 or definition.get('min_amount') == 1000 or 1000 in definition.values()
    has_cutoff_date = '2024-01-01' in str(definition) or definition.get('no_gifts_since') == '2024-01-01'

    if not (has_year_2023 and has_min_1000 and has_cutoff_date):
        return {"result": "others"}

    # Identify qualifying donors from final database
    # Donors who gave >= 1000 total in 2023
    donors_2023_query = """
        SELECT donor_id, SUM(amount) as total_2023
        FROM donations
        WHERE strftime('%Y', donation_date) = '2023'
        AND currency = 'USD'
        GROUP BY donor_id
        HAVING SUM(amount) >= 1000
    """

    donors_2023 = safe_query(final_db_path, donors_2023_query, ())
    if not donors_2023:
        return {"result": "others"}

    # Filter to only those with NO donations since 2024-01-01
    qualifying_donor_ids = set()
    for donor_row in donors_2023:
        donor_id = donor_row[0]

        # Check if this donor has any donations on or after 2024-01-01
        recent_donations_query = """
            SELECT COUNT(*) 
            FROM donations 
            WHERE donor_id = ? 
            AND donation_date >= '2024-01-01'
        """
        recent_count = safe_query(final_db_path, recent_donations_query, (donor_id,))

        if recent_count and recent_count[0][0] == 0:
            qualifying_donor_ids.add(donor_id)

    if len(qualifying_donor_ids) == 0:
        return {"result": "others"}

    # Check segment_members table for this segment
    members_query = "SELECT donor_id FROM segment_members WHERE segment_id = ?"
    segment_members = safe_query(final_db_path, members_query, (segment_id,))

    if not segment_members:
        return {"result": "others"}

    actual_member_ids = set(row[0] for row in segment_members)

    # Verify exact match - no extra donors, no missing donors
    if actual_member_ids != qualifying_donor_ids:
        return {"result": "others"}

    # All checks passed
    return {"result": "complete"}

