for name in ['gen_db.jsonl','gen_sample.jsonl','gen_verifier.pure_code.jsonl']:
 for l in (root/name).open():
  x=json.loads(l)
  if x['scenario']==scenario and (name"'!='"'gen_verifier.pure_code.jsonl' or x['task_idx']==6):records[name]=x;break
c=sqlite3.connect(':memory:')
for t in records['gen_db.jsonl']['db_schema']['tables']:
 c.execute(t['ddl'])
 for q in t.get('indexes',[]):c.execute(q)
 for q in t.get('examples',[]):c.execute(q)
c.commit();c.execute('PRAGMA foreign_keys = ON');errors=[]
for t in records['gen_sample.jsonl']['sample_data']['tables']:
 for q in t.get('insert_statements',[]):
  try:c.execute(q)
  except sqlite3.Error as e:errors.append(str(e))
c.commit();c.execute('PRAGMA query_only = ON')
class Conn:
 def cursor(self):return c.cursor()
 def close(self):pass
proxy=types.SimpleNamespace(**{n:getattr(sqlite3,n) for n in dir(sqlite3) if not n.startswith('__')});proxy.connect=lambda *args,**kwargs:Conn()
real_import=builtins.__import__
def local_import(name,*args,**kwargs):return proxy if name=='sqlite3' else real_import(name,*args,**kwargs)
ns={'__builtins__':dict(vars(builtins),__import__=local_import)}
exec(compile(records['gen_verifier.pure_code.jsonl']['verification']['code'],'<recorded verifier>','exec'),ns)
